<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {useRoute} from 'vue-router';import AdminDialog from '../../shared/ui/AdminDialog.vue';import RemoteSelect from './RemoteSelect.vue';import PageState from './PageState.vue';import {relationEndpoint,api,mutate,text,opts,useTask,useDirty,type DTO,type Page} from './shared';
const props=defineProps<{caseId:string;item?:DTO<'Stage2ChangeItemView'>}>(),emit=defineEmits<{close:[];saved:[]}>(),route=useRoute(),{busy,error,run}=useTask();
const resourceId=ref(props.item?.resource_id??String(route.query.resource??'')),action=ref(props.item?.action??String(route.query.action??'change_owner')),assignee=ref(props.item?.assignee_person_id??''),values=ref<Record<string,string>>({}),resource=ref<DTO<'ResourceView'>>(),relations=ref<DTO<'Stage2ResourceRelationView'>[]>([]),bindings=ref<DTO<'Stage2BindingView'>[]>([]),operation=ref<DTO<'Stage2PreparedOperationView'>>(),dirty=ref(false),discard=ref(false);
const actions=['change_owner','change_organization','change_visibility','grant_use','remove_use','transfer_controller','change_binding','change_mailbox_address','change_management_relation','rotate_credential','revoke_credential','revoke_credential_grant','replace_key','disable_resource','retire_resource','reactivate_resource'];
if(props.item)values.value=Object.fromEntries(Object.entries(props.item.proposal).filter(([k])=>k!=='action').map(([k,v])=>[k,String(v??'')]));
if(route.query.operation)values.value.operation_id=String(route.query.operation);if(route.query.credential)values.value.credential_id=String(route.query.credential);if(route.query.grant)values.value.credential_grant_id=String(route.query.grant);
useDirty(()=>dirty.value,()=>busy.value);watch([resourceId,action,assignee,values],()=>dirty.value=true,{deep:true});
function initialOrganization(){if(action.value==='change_organization'&&resource.value){if(!('company_id' in values.value))values.value.company_id=resource.value.confirmed_company?.id??'';if(!('owning_department_id' in values.value))values.value.owning_department_id=resource.value.owning_department?.id??'';}}
watch(action,initialOrganization);
async function load(){if(!resourceId.value)return;await run(async()=>{resource.value=await api.get<DTO<'ResourceView'>>('/resources/'+resourceId.value);initialOrganization();const r=await api.get<Page<DTO<'Stage2ResourceRelationView'>>>(`/resources/${resourceId.value}/relations?page_size=100`);relations.value=r.items;if(r.pagination.has_next)throw new Error('该资源有超过 100 条关联，请先从资源详情缩小具体变更对象。');if(resource.value.account){const b=await api.get<Page<DTO<'Stage2BindingView'>>>(`/resources/${resourceId.value}/bindings?page_size=100`);bindings.value=b.items;if(b.pagination.has_next)throw new Error('绑定超过 100 条，请从具体绑定发起变更。');}else bindings.value=[];if(values.value.operation_id)operation.value=await api.get<DTO<'Stage2PreparedOperationView'>>('/credential-operations/'+values.value.operation_id);});}watch(resourceId,load,{immediate:true});
const assignments=computed(()=>(resource.value?.people??[]).filter(p=>p.confirmation==='confirmed'&&(!p.valid_to||new Date(p.valid_to)>new Date())));
const fields=computed(()=>{
 const remote=(key:string,label:string,endpoint:string,required=true)=>({key,label,endpoint,required,options:undefined as {value:string;label:string}[]|undefined});
 const select=(key:string,label:string,options:{value:string;label:string}[],required=true)=>({key,label,options,required,endpoint:undefined});
 switch(action.value){
 case 'change_owner':return [remote('to_person_id','新负责人','/people')];
 case 'change_organization':return [remote('company_id','归属公司','/companies',false),remote('owning_department_id','归属部门','/departments',false)];
 case 'change_visibility':return [select('visibility_scope','可见范围',opts(['restricted','department','company']))];
 case 'grant_use':return [remote('person_id','使用人','/people')];
 case 'remove_use':case 'transfer_controller':return [select('assignment_id','当前人员关系',assignments.value.filter(p=>p.role===(action.value==='remove_use'?'use':'controller')).map(p=>({value:p.assignment_id,label:p.person.display_name+' · '+text(p.role)}))),...(action.value==='transfer_controller'?[remote('to_person_id','新控制人','/people')]:[])];
 case 'change_binding':return [select('binding_id','现有绑定',bindings.value.filter(b=>!b.valid_to).map(b=>({value:b.id,label:text(b.purpose)+' · '+(b.contact.masked_value)}))),remote('new_contact_identity_id','新身份','/contact-identities')];
 case 'change_mailbox_address':return [remote('new_contact_identity_id','新邮箱身份','/contact-identities')];
 case 'change_management_relation':return [select('relation_id','现有关联',relations.value.filter(r=>r.source.id===resourceId.value&&!r.valid_to).map(r=>({value:r.id,label:text(r.relation_type)+' → '+r.target.name}))),remote('proposed_target_id','新的目标资源',relationEndpoint(relations.value.find(r=>r.id===values.value.relation_id)?.relation_type??'managed_by'))];
 case 'replace_key':return [remote('replacement_resource_id','替换后的密钥资源','/resources?type_code=api_key')];
 default:return [];
 }
});
const requiresOperation=computed(()=>['rotate_credential','revoke_credential','revoke_credential_grant'].includes(action.value));
function close(){if(busy.value)return;if(dirty.value)discard.value=true;else emit('close');}
async function submit(){await run(async()=>{if(!resource.value?.capabilities.edit)throw new Error('当前资源不能修改');const proposal:Record<string,unknown>={action:action.value};for(const f of fields.value)proposal[f.key]=values.value[f.key]||null;if(requiresOperation.value){if(!operation.value||operation.value.resource_id!==resourceId.value||operation.value.status!=='prepared')throw new Error('请先在当前资源凭据中准备有效操作');proposal.operation_id=operation.value.id;if(action.value==='revoke_credential_grant')proposal.credential_grant_id=values.value.credential_grant_id;else proposal.credential_id=operation.value.credential_id;}await mutate(props.item?'/change-items/'+props.item.id:`/change-cases/${props.caseId}/items`,{...(props.item?{expected_version:props.item.version}:{resource_id:resourceId.value}),assignee_person_id:assignee.value||null,proposal},props.item?'PATCH':'POST');dirty.value=false;emit('saved');emit('close');});}
</script>
<template><AdminDialog open :title="item?'修订治理事项':'添加治理事项'" description="提案只描述将要改变的事实；提交或记录执行都不会提前覆盖正式数据。" title-id="proposal-title" @close="close"><form class="contents" @submit.prevent="submit"><div class="admin-dialog-body space-y-3"><PageState :busy="busy" :error="error" @retry="load"/><div v-if="discard" class="admin-notice admin-notice-warning">丢弃未保存提案？<button type="button" class="btn-secondary ml-2" @click="emit('close')">丢弃</button><button type="button" class="btn-ghost" @click="discard=false">继续填写</button></div><fieldset :disabled="busy" class="space-y-3"><label class="block"><span class="admin-form-label">作用资源 *</span><RemoteSelect v-if="!item" v-model="resourceId" endpoint="/resources" label="作用资源" required/><p v-else class="text-sm">{{resource?.name}}</p></label><div class="grid gap-3 sm:grid-cols-2"><label><span class="admin-form-label">实际变更 *</span><select v-model="action" class="admin-field"><option v-for="a in actions" :value="a">{{text(a)}}</option></select></label><label><span class="admin-form-label">执行人（可选）</span><RemoteSelect v-model="assignee" endpoint="/people" label="执行人"/></label><label v-for="f in fields" :key="f.key"><span class="admin-form-label">{{f.label}} {{f.required?'*':''}}</span><RemoteSelect v-if="f.endpoint" v-model="values[f.key]" :endpoint="f.endpoint" clear-on-endpoint-change :label="f.label" :required="f.required"/><select v-else v-model="values[f.key]" class="admin-field" :required="f.required"><option value="">请选择</option><option v-for="o in f.options" :value="o.value">{{o.label}}</option></select></label></div><p v-if="action==='change_organization'" class="text-xs text-gray-500">请选择变更后的完整归属；保留当前选择表示维持对应归属，留空表示清空该归属。</p><div v-if="requiresOperation" class="admin-notice admin-notice-info"><p v-if="operation">已准备 {{text(operation.action)}} · {{text(operation.status)}} · 有效至 {{operation.expires_at}}</p><p v-else>请先在资源详情的凭据分区准备轮换或撤销操作，再从该入口进入治理。</p><RouterLink v-if="resourceId" :to="'/resources/'+resourceId" class="text-link">进入当前资源凭据</RouterLink></div><p v-if="['disable_resource','retire_resource','reactivate_resource'].includes(action)" class="text-xs text-gray-500">当前状态：{{text(resource?.lifecycle)}}。完成实际执行并由独立人员复核后更新系统事实。</p></fieldset></div><footer class="admin-dialog-footer"><button type="button" class="btn-secondary" :disabled="busy" @click="close">取消</button><button class="btn-primary" :disabled="busy||!resource||Boolean(error)">保存提案</button></footer></form></AdminDialog></template>
